#!/usr/bin/env python3
"""
Round 99b (culprits), 28 September 2026. Round 98b must be applied first.

Biodiversity loss refiled in the owner's order; Places that matter most for
species in five parts; the critical habitat, intactness and intact forest rows
each one row with parts; own copies of the 2017 ecoregions and the intact
forests; the FAO zones and the nematodes coloured; the fungi row mended.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ""
NOTE = '## Round 99b (28 September)\n\nNeeds round 98b (runs after it by name). Tiles patch round99b_tiles.py beside it.\n\n- Biodiversity loss in the owner\'s order: Land Use and Ecoregions; Places that\n  matter most for species (Where species are threatened, Protected areas,\n  Species richness, Wild and intact places, Where animals gather and migrate);\n  Disturbance; Birds; Fish; Soil biodiversity; Wildlife and timber crime;\n  Companies and financiers. Protected and conserved areas and Intact and\n  primary forests headings gone (their rows moved in). BIO_* constants and the\n  first block of CATALOGUE_BY_TITLE.\n- Global Safety Net: ITTs under Invasion of humans; HM90 black (27, same asset\n  and value as the white 40) and "Land" (42) out; climate stabilization areas\n  under Climate > Carbon dioxide > Carbon stored in nature; constrained\n  reforestation also under Deforestation > Forest cover; natural/barren,\n  semi-natural and herbaceous land under Land Use and Ecoregions; the two BII\n  halves one row (bundle bii); critical habitat land and sea one row (bundle\n  crithab, with own_critical_habitat); conservation priorities grown and light\n  (GSN_GROW 98).\n- FAO ecological zones coloured by zone (GFW_COLOUR_BY gez_term); FAO zones and\n  both SBTN Natural Lands rows under Land Use and Ecoregions only.\n- Own copies (tiles): ecoregions_2017 (RESOLVE, pmchoose classes by BIOME_NUM;\n  GSN\'s row 28 out) and ifl_2000 to ifl_2025 (pmvector own; GFW\'s year rows\n  out) inside bundle ifl with GFW\'s all-years picture.\n- WWF ecoregions retitled (2001 version, 867 regions).\n- soil_nematodes coloured by Total_Number; soil_spun retitled.\n- Kept, not deleted: Nusantara\'s protected areas (Equatorial Asia) and GFW\'s\n  licensed WDPA: both carry each area\'s name and details, which Global Safety\n  Net\'s pictures do not.\n\n'
HEAD = "## Round 99b (28 September)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round99b: run from the culprits repository root")
    if "## Round 98b" not in (root / "HANDOFF.md").read_text(encoding="utf-8"):
        sys.exit("round99b: round 98b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round99b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round99b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round99b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round 98b")
        h.write_text(text[:at] + NOTE + "\n" + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
